package net.civeira.phylax.features.document.theme.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.ThemeApi;
import net.civeira.phylax.generated.openapi.model.ThemeApiDto;

@RequiredArgsConstructor
@ApplicationScoped
public class ThemeController implements ThemeApi {

  /**
   * ThemeApiDto
   *
   * @autogenerated ApiControllerGenerator
   */
  private final ThemeCreateController createController;

  /**
   * Theme
   *
   * @autogenerated ApiControllerGenerator
   */
  private final ThemeDeleteController deleteController;

  /**
   * Disable
   *
   * @autogenerated ApiControllerGenerator
   */
  private final ThemeDisableController disableController;

  /**
   * Enable
   *
   * @autogenerated ApiControllerGenerator
   */
  private final ThemeEnableController enableController;

  /**
   * Theme
   *
   * @autogenerated ApiControllerGenerator
   */
  private final ThemeListController listController;

  /**
   * Theme
   *
   * @autogenerated ApiControllerGenerator
   */
  private final ThemeRetrieveController retrieveController;

  /**
   * ThemeApiDto
   *
   * @autogenerated ApiControllerGenerator
   */
  private final ThemeUpdateController updateController;

  /**
   * @autogenerated ApiControllerGenerator
   * @param theme
   * @return
   */
  @Override
  public Response themeApiCreate(ThemeApiDto theme) {
    return createController.themeApiCreate(theme);
  }

  /**
   * @autogenerated ApiControllerGenerator
   * @param uid
   * @return
   */
  @Override
  public Response themeApiDelete(final String uid) {
    return deleteController.themeApiDelete(uid);
  }

  /**
   * @autogenerated ApiControllerGenerator
   * @param uid
   * @return
   */
  @Override
  public Response themeApiDisable(final String uid) {
    return disableController.themeApiDisable(uid);
  }

  /**
   * @autogenerated ApiControllerGenerator
   * @param uid
   * @return
   */
  @Override
  public Response themeApiEnable(final String uid) {
    return enableController.themeApiEnable(uid);
  }

  /**
   * @autogenerated ApiControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param name
   * @param tenant
   * @param tenants
   * @param limit
   * @param sinceUid
   * @param sinceName
   * @param order
   * @return
   */
  @Override
  public Response themeApiList(final List<String> uids, final String search, final Boolean global,
      final String name, final String tenant, final List<String> tenants, final Integer limit,
      final String sinceUid, final String sinceName, final String order) {
    return listController.themeApiList(uids, search, global, name, tenant, tenants, limit, sinceUid,
        sinceName, order);
  }

  /**
   * @autogenerated ApiControllerGenerator
   * @param uid
   * @return
   */
  @Override
  public Response themeApiRetrieve(final String uid) {
    return retrieveController.themeApiRetrieve(uid);
  }

  /**
   * @autogenerated ApiControllerGenerator
   * @param uid
   * @param theme
   * @return
   */
  @Override
  public Response themeApiUpdate(final String uid, ThemeApiDto theme) {
    return updateController.themeApiUpdate(uid, theme);
  }
}
